WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (414::BIGINT, 'Buen profe pero muy malo para atender consultar, se nota que tiene favoritismo con algunos estudiantes para la disponibilidad de atenderlos. Llevo todo el semestre intentando que me conteste los correos o por teams y nada. Incluso me dejó en visto consultas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-05-12T00:00:00+00:00'::TIMESTAMPTZ, '57c84524fb83bf15560d8a1660c0ba52ac4e76844b672d9cae6d199238599b36'::TEXT, ARRAY[3980]::BIGINT[]),
    (414::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-09-09T00:00:00+00:00'::TIMESTAMPTZ, '9d107fa89cac17744a837b185a692fa72c392a27455751fc6bc2e8d6ffee9646'::TEXT, ARRAY[1325]::BIGINT[]),
    (414::BIGINT, 'Es una lástima que un profe tan bueno haga cátedra con otros profes que lo único que buscan es que uno se quede en el curso y hagan exámenes imposibles. Se pierde totalmente la lógica de la evaluación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-08T00:00:00+00:00'::TIMESTAMPTZ, '8f48a13cbccfee4f853574ba77cda647b45dc04fd4f21e456fddfa4da675bf40'::TEXT, ARRAY[1325]::BIGINT[]),
    (414::BIGINT, 'Es de lo mejor de la escuela de electro, excelente profe, sin duda matricularía cualquier curso con él, explica bien, da mucha ayuda con las dudas, revisa normal, nada más ponerle bonito con las practicas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e1e5869734c9d60e49e3c8960256d5b4284cde6fe576eb502d11b41d2b1e551d'::TEXT, ARRAY[1325]::BIGINT[]),
    (414::BIGINT, 'Excelente profesor. En los proyectos y examenes da puntos extra y siempre esta dispuesto a ayudarlo a uno mucho. Con el se aprende Verilog lo cual ayuda mucho. La unica queja es que solo hace 2 examenes entonces el examen final tiene bastante materia'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1fb69c2285c32363d05b03a38c74c61c5c268474746a6d5474f1bc6ca242c6ea'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4ca84641d9c52f5223fc91bf37d64e129d5db98b6a050a74249196073ea5a0c6'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Excelente profesor, muy buena persona y siempre está dispuesto a ayudar en consulta. Da puntos extra en los exámenes y proyectos, que ayudan mucho para subir las notas. Domina muy bien la materia del curso y usa tiempo de clase para el uso de System Verilog usado en taller de Diseño Digital.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8a25932260d629d916dc5b8013d6dff87eb17e08c1ecf1c1e47bcbd05ae36fbe'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'De los mejores profesores de la escuela sin duda. Es demasiado pura vida. El curso es pesado en sí, principalmente si llega con malas bases de digitales, pero el profe explica super claro y ayuda demasiado. Es indispensable un buen grupo de trabajo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6889aae89f802390f5fa12b8c1fa8ad6a428d4d0a20260eac8c100043f89b5fa'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'Sin duda uno de los mejores profes de la escuela y la mejor opción para llevar el taller, ayuda un montón, explica de 10 y no califica tan rudo como el otro profe. Es esencial conseguir un buen grupo de trabajo, ya que los proyectos son muy pesados. Meta con el sin miedo'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'b9482cf97ee2510adc0aa447ba6511be5f003bc22836045f2865e97c39508efd'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'Pablo es sin duda alguna el mejor profe que hay en la carrera. Se le hace demasiado fácil transmitir conocimiento (y vaya que tiene). El curso es muy pesado, pero el profe lo hace super llevadero. Tenga buen equipo de trabajo y vaya a consulta, y el curso se pasa bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '51775b38a16ff9996ddd11847d9bcd2d9b8ee4a948705a4e68be0cbad527e546'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'El profe Pablo es de lejos, lo mejor que tiene la escuela de Electro. El curso es pesado, pero solo de conseguirse un buen grupo de trabajo y lo demás es solo dedicarle buen tiempo. El profe ayuda un montón en consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '68de50c3fb706a2e3b2cfb313ad73d01649ae3486c569230eb634d4c53f72259'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'El curso es pesado por su naturaleza, más si en diseño lógico no se profundizó lo suficiente en verilog, pero el profe es una teja y ayuda en todos los aspectos que le es posible en los proyectos y a la hora de calificar. Este profe es super accesible y la mejor opción.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '497986cb604b89072ce0df612daf3ee0babcab92c448fee3c02844bbfdc4f34a'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'Es sumamente bueno, las clases son claras y se interesa porque la gente aprenda y diversifique el conocimiento con implementación en la vida cotidiana 10 /10.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '93d64d1b4f6dd720f9fa3b5fbad45dbf2291aa91d12f3732e19398d420d97772'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Las clases del profe son muy claras y concisas respecto a los temas que explica de manera apasionada. Los exámenes son sencillos completamente relacionados con la materia vista en clase con la ventaja de que el profe utiliza Verilog (un HDL) que simplifica la puesta en práctica de los conceptos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'ab957a301042f7fe3ac07446df3c16d6715958ca0fc5d730d133f02e96b8f535'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Buen profe, sabe mucho de la materia, buena gente, no es estricto con la asistencia ni con las fechas de entrega, se nota que le gusta la materia, aunque en sí las clases pueden ser muy pesadas. Califica suave, proyectos grupales muy sencillos, el problema es que quizás no se aprende tanto'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '8a3ca7c428eb9a1e9c9dc8dee25108310523c935b8b3deb413b7ba453c512dee'::TEXT, ARRAY[3069, 1339, 1413]::BIGINT[]),
    (414::BIGINT, 'Excelente profesor. Explica bien, la cantidad de asignaciones que deja es adecuada, examenes y tareas no fáciles pero nada del otro mundo y en general, super recomendado este profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '755e0e130155562af2b94f660a7c558aef06f85e026ed90bafa1b09e337a8582'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Meta sin miedo, Ponce es un crack. El curso lo hace sencillón, pero estudie. Enseña Verilog que a huevo tenemos que usar en Taller de Digitales, diría que es mejor opción de Bigotes por ese motivo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c6937059a5f18643f981e1f07d20842549501ff82336468f9fa293ee116ec9cf'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Excelente profesor. Se nota que le interesa que uno aprenda y ayuda en todo lo que puede. El curso es síper interesante, y hay que tarbajar mucho pero vale la pea por todo el aprendizaje. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '8cf9bf441706b8bd89dd3baacd09563d6ecb57f2a6dd83b2d0e6f621ac0a03d4'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'Este profe es super buena gente, no es de esos profes orgullosos y siempre esta dispuesto a ayudarlo a uno en lo que necesite. Explica muy bien y no necesita hacer el curso tan pesado para que uno entienda, super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '825dcde4ec9b4bf45bbf7ddebd0e85398a9f450412b1b735873a7186443aaab4'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Una persona a la que dan ganas de escuchar. Se preocupa mucho porque los estudiantes aprendan, aclara de buena manera las dudas. Enseña verilog y usa ejemplos de vida real. Califica muy rápido las evaluaciones'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'eb6a6f2a766a16bf9a40db918d6aa6dac0967e61328fdaaed477a477c7b9171e'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'Es un amor de persona y excelente profesor. Explica claro, los exámenes no son tan complicados y enseña a usar Verilog. Se preocupa porque uno aprenda y entienda la materia. No duden en matricular con él'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f550577243cbf3b11b1a90986fb2e2e1dbac908ee0b1553a2f3bc24a59687802'::TEXT, ARRAY[1282]::BIGINT[]),
    (414::BIGINT, 'De ese tipo de profesores que necesita la universidad, el curso ya de por sí tiene demasiada materia pero el profesor lo adaptó apropiadamente, eso sí algunas clases (la mayoría) son muy largas. Exámenes son orales pero califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '94e25aa9693cde299d2e26151df6cd3e8882de220940742a37657a0cb459a427'::TEXT, ARRAY[3069]::BIGINT[]),
    (414::BIGINT, 'Muy buen profe, siempre ayuda y es muy atento. El curso es complicado debido a que las bases de Diseño Digital son malas, pero el profe intenta explicar conceptos importantes para poder realizar los proyectos. Si se necesita más tiempo lo da. Es de los mejores profes que he tenido :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '384f2a22e4cba2e20ec683a19bb414a478bdf9ded6ee335f97706c862d7e6ae0'::TEXT, ARRAY[1301]::BIGINT[]),
    (414::BIGINT, 'Es un profe que se interesa mucho porque uno aprenda, cualquier duda en clase no duda en resolverla de la mejor manera. Califica bastante justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-07T00:00:00+00:00'::TIMESTAMPTZ, 'eae8805ed41e64589e05267a1b90c6256d139493cfb3384a656a61990a89b193'::TEXT, ARRAY[1282]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
